        public static string Get(string key)
        {
            string[] values;
            if (!Strings.TryGetValue(key, out values)) return UiText.Get(key);
            for (int i = 0; i < UiText.LanguageCodes.Length; i++) if (UiText.LanguageCodes[i] == UiText.Language) return values[i];
            return values[0];
        }
    }
